import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../../components/cliente.css";
//imagenes (si tienes una imagen de perfil, impórtala aquí)
// import userProfilePic from '../../assets/user-avatar.webp'; 

// header y footer
import Header from '../../components/Header_c.jsx'; 
// import Footer from '../../components/Footer.jsx'; // Si usas un Footer aquí

export default function PerfilForm() { 
    return (
        <div className="dashboard-layout">
            <Sidebar />

            {/* Aquí comienza la primera etiqueta <main> */}
            <main className="contenido">
                <HeaderPerfil />

                <div className="perfil-container"> {/* Cambié a <div> para evitar tener <main> anidados */}
                    <div className="form-card">
                        <h2 className="form-title">Cambiar datos</h2>

                        {/* 1. Agregué la etiqueta <form> para que envuelva todos los campos y el botón */}
                        <form>
                            <div className="form-group">
                                {/* Recomendación: Usar defaultValue en lugar de value */}
                                <input type="text" id="nombre_usuario" name="nombre_usuario" defaultValue="Maria Lopez" placeholder="" required />
                                <label htmlFor="nombre_usuario">Nombre de usuario</label>
                            </div>

                            <div className="form-group">
                                {/* 2. CORRECCIÓN: 'placehoder' -> 'placeholder' y 'name' a 'correo' */}
                                <input type="email" id="correo" name="correo" defaultValue="MariLz45@gmail.com" placeholder="" required />
                                <label htmlFor="correo">Correo electrónico</label>
                            </div>

                            <div className="form-group">
                                <input type="tel" id="telefono" name="telefono" defaultValue="3287865455" placeholder="" required />
                                <label htmlFor="telefono">Numero de teléfono</label>
                            </div>

                            <div className="document-group">
                                <div className="document-type">
                                    <select 
                                        id="tipo_doc" 
                                        name="tipo_doc" 
                                        defaultValue="CC"
                                        required
                                    >
                                        <option value="CC">Cédula de Ciudadanía</option>
                                        <option value="TI">Tarjeta de Identidad</option>
                                        <option value="CE">Cédula de Extranjería</option>
                                    </select>
                                    <label htmlFor="tipo_doc">Tipo de documento</label>
                                </div>

                                <div className="document-number">
                                    <input type="text" id="numero_doc" name="numero_doc" defaultValue="1014937269" placeholder="" required/>
                                    <label htmlFor="numero_doc">Número de documento</label>
                                </div>
                            </div>

                            <button type="submit" className="btn-guardar">Guardar</button>
                        </form> {/* <--- 3. CORRECCIÓN: Cierre de la etiqueta <form> */}
                    </div>
                {/* 4. CORRECCIÓN: Cierre de la etiqueta que envuelve el formulario (era un <main> anidado) */}
                </div> 
            </main> {/* <--- Cierre de la primera etiqueta <main> */}
        {/* 5. CORRECCIÓN: Eliminé el caracter flotante '/' */}
        </div>
    );
}
